def power_iteration(a: list[list[float]], steps: int) -> float:

    n: int = len(a)
    v: list[float] = []
    for i in range(n):
        v.append(1.0)
    eig: float = 0.0
    for step in range(steps):
        w: list[float] = []
        for i in range(n):
            acc: float = 0.0
            for j in range(n):
                acc += a[i][j] * v[j]
            w.append(acc)
        norm: float = 0.0
        for i in range(n):
            norm += w[i] * w[i]
        norm = norm ** 0.5
        num: float = 0.0
        den: float = 0.0
        for i in range(n):
            num += w[i] * v[i]
            den += v[i] * v[i]
        eig = num / den
        for i in range(n):
            v[i] = w[i] / norm
    return eig
